x_comment('x_ClusterBomb-CBU89',"The #$ClusterBomb-CBU89 Gator Mine, a 1,000-pound cluster munition containing antitank and antipersonnel mines, consists of a SUU-64 Tactical Munitions Dispenser with 72 antitank mines, 22 antipersonnel mines, and an optional FZU-39 proximity sensor. Mine arming begins when the dispenser opens. Mine detonation is initiated by target detection, mine disturbance, low battery voltage, and a self-destruct time-out. The antitank mine is a magnetic sensing submunition effective against tanks and armored vehicles. The antipersonnel mine has a fragmenting case warhead triggered by trip wires. The US Air Force employed 1,105 CBU-89s during the Gulf War.  The Gator mine system provides a means to emplace minefields on the ground rapidly using high-speed tactical aircraft.  The minefields are used for area denial, diversion of moving ground forces, or to immobilize targets to supplement other direct attack weapons.") :- x_cid(a65b127555f3e0).
