x_comment('x_Bomb-GBU24',"The Guided #$Bomb-GBU24 Low Level Laser Guided Bomb [LLLGB] consists of either a 2,000-pound #$AerialBomb-MK84 general purpose or BLU-109 penetrator bomb modified with a Paveway III low-level laser-guided bomb kit to add the proportional guidance in place of the bang-bang type used in the Paveway II. The LLLGB was developed in response to Sophisticated enemy air defenses, poor visibility, and to counter limitations in low ceilings. The weapon is designed for low altitude delivery and with a capability for improved standoff ranges to reduce exposure. The GBU-24 LLLGB/Paveway III has low-level, standoff capability of more than 10 nautical miles. Performance envelopes for all modes of delivery are improved because the larger wings of the GBU-24 increases maneuverability. Paveway III also has increased seeker sensitivity and a larger field of regard.") :- x_cid(a65b127555f3fc).
