x_comment('x_Bomb-MolotovCocktail',"A specialization of #$Bomb-Incendiary and #$ProjectileWeapon.  Each instance of #$Bomb-MolotovCocktail is a breakable container filled with a flammable liquid.  A wick, usually made from cloth, is lit before hurling.  The Molotov Cocktail shatters on impact and either burns or incinerates the target.  The Molotov Cocktail is used mostly by rioters, not military or police personnel.") :- x_cid(a65b127555f43c).
