x_comment('x_ProjectileShell-M60',"#$ProjectileShell-M60 is a 105mm projectile and consists of a  hollow one-piece steel forging. A fuze adapter is screwed into the body and brazed in place. The DB mustard gas blister agent is added and the burster well is then press-fit into the fuze adapter followed by the M5 tetrytol burster being installed into the burster well. A fuze well cup, made of either aluminum or Bakelite, is installed by first coating the lower interior threads of the fuze adapter with sealing compoudn or cement and then screwing the cup down into the fuze adapter. The M60 is then closed by screwing on an M57 or M51A5 point detonating fuze and staking it in place. Staking is an operation in which a punch is used to deform the metal of the fuze so that the metal is pushed into a notch in the projectile body, thereby locking the threaded joint. The projectiles are stored 24 per wooden pallet with 2 pallets butted together with steel banding.") :- x_cid(a65b127555f441).
xc_microtheory(a65b127555f441,x_ModernMilitaryWeaponsMt).
