x_comment('x_ClusterBomb-MK20',"The #$ClusterBomb-MK20, \"Rockeye\" is a free-fall, unguided cluster weapon designed to kill tanks and armored vehicles. The system consists of a clamshell dispenser, a mechanical MK-339 timed fuze, and 247 dual-purpose armor-piercing shaped-charge bomblets. The bomblet weighs 1.32 pounds and has a 0.4-pound shaped-charge warhead of high explosives, which produces up to 250,000 psi at the point of impact, allowing penetration of approximately 7.5 inches of armor. Rockeye is most efficiently used against area targets requiring penetration to kill.") :- x_cid(a65b127555f45b).
xc_microtheory(a65b127555f45b,x_ModernMilitaryWeaponsMt).
