x_comment('x_Missile-AIM-120',"The #$Missile-AIM-120 advanced medium-range air-to-air missile (AMRAAM) is a new generation air-to-air missile.  The AMRAAM weighs 340 pounds and uses an advanced solid-fuel rocket motor to achieve a speed of Mach 4 and a range in excess of 30 miles. In long-range engagements AMRAAM heads for the target using inertial guidance and receives updated target information via data link from the launch aircraft. It transitions to a self-guiding terminal mode when the target is within range of its own monopulse radar set. The AIM-120 also has a \"home-on-jam\" guidance mode to counter electronic jamming. With its sophisticated avionics, high closing speed, and excellent end-game maneuverability, chances of escape from AMRAAM are minimal. Upon intercept an active-radar proximity fuze detonates the 40-pound high-explosive warhead to destroy the target. At closer ranges AMRAAM guides itself all the way using its own radar, freeing the launch aircraft to engage other targets.") :- x_cid(a65b127555f45e).
xc_microtheory(a65b127555f45e,x_ModernMilitaryWeaponsMt).
