x_comment('x_ProjectileShell-RocketAssisted',"There are two main reasons for developing #$ProjectileShell-RocketAssisted: (1) to extend the range over standard gun systems, and (2) to allow for lighter mount and barrel design and reduce excessive muzzle flash and smoke by reducing the recoil and setback forces of standard gun systems. Since the ranges are different, the above two objectives represent opposite approaches in the development of rocket-assisted projectiles. Normally, one or the other establishes the performance of the rocket-assisted projectile under development although some compromise in the two approaches may be established by the design objectives.") :- x_cid(a65b127555f46e).
