x_comment(x_ClusterMunition,"#$ClusterMunitions are a type of projectile explosive designed to break up into many smaller projectiles, either in-flight or  upon impact, to achieve an expanded area of effect.  Such munitions can be launched toward/delivered to their targets by aircraft (as #$AerialBombs), by artillery systems (as #$ArtilleryShells), or by missile-based  systems.  They may contain anti-personnel submunitions, anti-armor submunitions, or both, as in 'dual purpose improved conventional munitions' or DPICMs.") :- x_cid(a65b127555f46f).
