x_comment('x_Bomb-VehicleDelivered',"A specialization of #$Bomb. Each instance of #$Bomb-VehicleDelivered is a device typically employed by a terrorist organization. Each instance is an explosive device that is brought into proximity to its target by covert means involving a #$TransportationDevice-Vehicle, e.g. an #$Automobile or a #$Motorboat. The vehicle may be driven to the vicinity of the target and evacuated by its driver prior to detonation, or it may be driven into the target by a suicide bomber or bombers who are killed when the device explodes.  Important specializations of #$Bomb-VehicleDelivered are #$CarBomb-VehicleDelivered and #$BoatBomb-VehicleDelivered (qq.v.).") :- x_cid(a65b127555f4a5).
