x_comment('x_ClusterBomb-CBU87',"The #$ClusterBomb-CBU87 is a 1,000-pound, Combined Effects Munition (CEM) for attacking soft target areas with detonating\n\nbomblets. The CBU-87 CEM, an all-purpose, air-delivered cluster weapons system, consists of a SW-65 Tactical Munitions Dispenser (TMD) with an optional FZU-39 proximity sensor. The BLU-97/B Combined Effects Bomb (CEB), effective against armor, personnel and material, contains a shaped charge, scored steel casing and zirconium ring for anti-armor, fragmentation and incendiary capability.") :- x_cid(a65b127555f4d5).
