x_comment('x_ATGMLauncher-Eryx',"#$ATGMLauncher-Eryx is a Short Range Anti-Armour Weapon (Heavy) or SRAAW(H). It is a portable system including the firing post, the tripod, the Mirabel thermal imager and the missile tube. It provides the infantry section and the armoured reconnaissance assault troop with an improved capability in accuracy and penetration. Fired from the shoulder or using the tripod, Eryx can defeat all modern static or moving tanks. With its tandem high explosive warhead, it is effective against bunkers, earth works, and armour targets even when equipped with explosive reactive armour (ERA). Eryx can operate in all weather conditions, in normal battlefield smoke and at night. Its high flexibility allows it to operate in open ground, wooded zones or an enclosed space in built-up areas.") :- x_cid(a65b127555f4e7).
