x_comment('x_Missile-AIM7',"The #$Missile-AIM7 Sparrow is a radar-guided, air-to-air missile with a high-explosive warhead. The versatile Sparrow has all-weather, all-altitude operational capability and can attack high-performance aircraft and missiles from any direction. The AIM/RIM-7 series is a semiactive, air-to-air, boost-glide missile, designed to be either rail or ejection launched. Semiactive, continuous wave, homing radar, and hydraulically-operated control surfaces direct and stabilize the missile on a proportional navigational course to the target. Propulsion for the missile is provided by a solid propellant rocket motor.") :- x_cid(a65b127555f4ec).
xc_microtheory(a65b127555f4ec,x_ModernMilitaryWeaponsMt).
