x_comment('x_ProjectileShell-M913',"The 105MM, High Explosive Rocket Assisted (HERA) #$ProjectileShell-M913 was developed to provide increased range and lethality for the M119 howitzer fielded with the light divisions. The projectile consists of TNT loaded, high fragmentation steel warhead. A rocket motor initiated by a pyrotechnic delay assembly at approximately 15 seconds in flight provides the maximum range of 19.5 km. In the rocket off mode, 14.5 km is obtained.") :- x_cid(a65b127555f4ed).
