x_comment('x_ATGMLauncher-Milan'," The #$ATGMLauncher-Milan consists of two main components, the launcher and the missile; these are simply clipped together to prepare the system for use. On firing, the operator has only to keep his aiming mark on the target and the Semi Automatic Command to Line of Sight (SACLOS) guidance system will do the rest. The missile is guided for its entire trajectory by an automatic device of remote control using the infra-red radiation (MILAN 1) or an electronic-flash lamp (MILAN 2). Milan, which was initially developed for the French and German infantry, is now in service in 41 countries all over the world.") :- x_cid(a65b127555f4f9).
