x_comment(x_viableBasisForWeaponType,"This relation attempts to encode an admittedly vague concept:  the idea that a particular substance is a 'viable basis' for being used in a weapon of a certain type (see also #$weaponBasisObjectType and #$weaponTypeBasisObjectType. As we are presently defining it (#$viableBasisForWeaponType WEAPON-TYPE BASIS-TYPE) entails that if a weapon of type WEAPON-TYPE which has BASIS-TYPE as the #$weaponBasisObjectType is used in an #$AttackOnTangible then, other things being equal, that attack has a high #$likelihood of being successful for the perpetrator (see #$successfulForAgents).") :- x_cid(a65b127555f4fb).
xc_microtheory(a65b127555f4fb,x_ModernMilitaryWeaponsMt).
