x_comment(x_PistolTokarevTT,"The Tokarev pistol was developed by F.V. Tokarev in 1930 and adopted by the Soviet army the same year. The production was started at the arms plant in Tula city. In 1933, the TT (Tula-Tokarev) was improved with a new locking system and a different disconnector. Up until 1942, over 521,000 of these pistols were produced in Russia. PM (Makarov)would then replace TT as the official Soviet military sidearm from 1954 to the present. ") :- x_cid(a65b127555f50d).
